CREATE TABLE customers (customer_id SERIAL PRIMARY KEY, customer_name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, phone TEXT);
CREATE TABLE users (user_id SERIAL PRIMARY KEY, customer_id INT REFERENCES customers(customer_id), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','customer')));
CREATE TABLE sites (site_id SERIAL PRIMARY KEY, site_name TEXT NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL);
CREATE TABLE equipment (equipment_id SERIAL PRIMARY KEY, equipment_name TEXT NOT NULL, equipment_type TEXT NOT NULL, rfid_tag TEXT UNIQUE NOT NULL, status TEXT NOT NULL DEFAULT 'Available' CHECK (status IN ('Available','Reserved','Active','Maintenance')));
CREATE TABLE requests (request_id SERIAL PRIMARY KEY, customer_id INT REFERENCES customers(customer_id), site_id INT REFERENCES sites(site_id), equipment_type TEXT NOT NULL, assigned_equipment_id INT REFERENCES equipment(equipment_id), start_date DATE NOT NULL, end_date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending','Approved','Rejected','Active','Completed')));
CREATE TABLE equipment_logs (log_id SERIAL PRIMARY KEY, equipment_id INT REFERENCES equipment(equipment_id), latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, runtime_hours DECIMAL(10,2) NOT NULL, idle_hours DECIMAL(10,2) NOT NULL, fuel_consumption DECIMAL(10,2) NOT NULL, timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX requests_equipment_dates_idx ON requests (assigned_equipment_id,start_date,end_date);
